// Market-sizing analysis pipeline — executes the systematic-market-sizing
// skill's 8 steps for one industry and produces a full SizingMatrix (the same
// schema the frozen hydraulic-breaker report renders from), so every analysis
// gets the rich chart report, not just summary cards.
//
// Data provenance rules:
//  - Quantitative content (anchor estimates, region weights, segment mixes,
//    baselines, CAGRs) is generated by the LLM from its market knowledge and
//    marked provenance='llm-estimate' — the UI banners it as unverified until
//    an analyst anchors (step 2) and cross-validates (step 6) it.
//  - Per-step summaries + pendingInputs record exactly what an analyst must
//    confirm before the matrix can be frozen and registry-registered (step 8).
//  - With no LLM configured, completeOrFallback degrades to deterministic
//    synthesis; the pipeline then emits a skeleton matrix flagged for manual
//    completion rather than invented numbers.

import type { Database } from "bun:sqlite";
import { ulid } from "../../../db/lib/ulid.ts";
import { completeOrFallback } from "./llm.ts";
import { researchSources } from "./web-research.ts";
import { SEGMENTS, type SizingMatrix } from "./market-sizing.ts";

export const PIPELINE_STEPS = [
  { no: 1, title: "축·프록시 구조 정의" },
  { no: 2, title: "기준 시장규모 산정 (다중 소스 교차)" },
  { no: 3, title: "권역·세그먼트 배분" },
  { no: 4, title: "셀별 CAGR·시나리오 밴드" },
  { no: 5, title: "성장률 정합성 확인" },
  { no: 6, title: "기업 공시 교차검증" },
  { no: 7, title: "분석 한계 목록" },
  { no: 8, title: "가정 레지스트리 등록" },
] as const;

const REGIONS = [
  { code: "china", label: "중국" },
  { code: "apac_ex_china", label: "아시아(중국 제외)" },
  { code: "north_america", label: "북미" },
  { code: "europe", label: "유럽" },
  { code: "mea", label: "중동·아프리카" },
  { code: "latam_row", label: "중남미/기타" },
] as const;

export interface StepSummary {
  step: number;
  summary: string;
  source: "llm" | "synthesis";
  pendingInputs: string[];
}

interface StepResult {
  summary: string;
  source: "llm" | "synthesis";
  pendingInputs: string[];
  json: Record<string, unknown> | null;
}

/** Ask the LLM for a JSON object; returns null when it cannot produce parseable JSON. */
async function askJson(industry: string, instruction: string): Promise<Record<string, unknown> | null> {
  const res = await completeOrFallback(
    [
      { role: "system", content: "You are a market-sizing analyst. Reply with ONE JSON object only — no prose, no markdown fences." },
      { role: "user", content: `산업: ${industry}\n${instruction}` },
    ],
    () => "NOT_JSON",
    { temperature: 0.2, maxTokens: 2000 },
  );
  if (res.source !== "llm") return null;
  const text = res.text.replace(/```json|```/g, "");
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start === -1 || end <= start) return null;
  try {
    return JSON.parse(text.slice(start, end + 1)) as Record<string, unknown>;
  } catch {
    return null;
  }
}

async function summarize(industry: string, step: number, title: string, context: string): Promise<{ summary: string; source: "llm" | "synthesis" }> {
  const res = await completeOrFallback(
    [
      { role: "system", content: "You are a new-business market analyst. Summarize one step of a market-sizing analysis in Korean, 2 sentences max, plain text." },
      { role: "user", content: `산업: ${industry}\n단계 ${step}: ${title}\n산출 데이터: ${context}` },
    ],
    () => `${industry} — ${title}: 방법론 절차에 따라 작성되었습니다.`,
    { maxTokens: 400 },
  );
  return { summary: res.text, source: res.source };
}

const num = (v: unknown, fallback: number): number => (typeof v === "number" && Number.isFinite(v) ? v : fallback);
const str = (v: unknown, fallback = ""): string => (typeof v === "string" && v.trim() ? v.trim() : fallback);

export async function runSizingPipeline(db: Database, analysisId: string): Promise<void> {
  const analysis = db
    .query(
      `SELECT a.id, a.industry_id, i.name_ko, i.ksic_code
       FROM market_sizing_analysis a JOIN md_industry i ON i.id = a.industry_id
       WHERE a.id = ?`,
    )
    .get(analysisId) as
    | { id: string; industry_id: string; name_ko: string; ksic_code: string | null }
    | null;
  if (!analysis) throw new Error(`analysis ${analysisId} not found`);
  const industry = analysis.name_ko;
  const now = () => new Date().toISOString();
  const advance = (step: number) => db.run("UPDATE market_sizing_analysis SET current_step = ? WHERE id = ?", [step, analysis.id]);
  const stepSummaries: StepSummary[] = [];

  // ── Step 1: 시장 구조 정의 (분석 축 + 산업 사슬 방향) ──
  advance(1);
  // 산업의 가치사슬 위치에 따라 분석 방향이 갈린다: downstream 산업은
  // 전방/전전방(수요처)을, upstream 산업은 후방/후후방(공급처)을 분석한다.
  const dirJson = await askJson(
    industry,
    `이 산업이 가치사슬에서 어디에 위치하는지와 인접 산업을 분석하세요. JSON: {"position":"upstream|midstream|downstream","note":"위치 판단 근거 한두 문장","relatedIndustries":[{"relation":"전방|전전방|후방|후후방","name":"산업명","note":"분석 포인트"}]}. position이 downstream/midstream이면 relation은 전방/전전방(수요처) 중심으로, upstream이면 후방/후후방(공급처) 중심으로 3~5개.`,
  );
  const chainDirection: SizingMatrix["chainDirection"] = {
    position: (["upstream", "midstream", "downstream"].includes(str(dirJson?.position)) ? str(dirJson?.position) : "midstream") as "upstream" | "midstream" | "downstream",
    note: str(dirJson?.note, "가치사슬 위치 미확정 — 분석가 확정 필요"),
    relatedIndustries: (Array.isArray(dirJson?.relatedIndustries) ? dirJson!.relatedIndustries : []).slice(0, 6).map((r) => ({
      relation: str(r.relation, "전방"),
      name: str(r.name, "—"),
      note: str(r.note) || undefined,
    })),
  };
  const POSITION_LABEL: Record<string, string> = { upstream: "상류(원자재·부품)", midstream: "중류(조립·가공)", downstream: "하류(완제품·수요처)" };
  const s1 = await summarize(
    industry,
    1,
    "시장 구조 정의",
    `가치사슬 위치는 ${POSITION_LABEL[chainDirection.position]} — ${chainDirection.position === "upstream" ? "후방/후후방(공급처)" : "전방/전전방(수요처)"} 산업을 분석 대상으로 삼습니다. 인접 산업 ${chainDirection.relatedIndustries.length}개 식별.`,
  );
  stepSummaries.push({ step: 1, ...s1, pendingInputs: ["프록시 체인의 통계 hop 수 확정 (체인 등급 산정)"] });

  // ── Step 2: anchor triangulation (LLM proposes source estimates) ──
  advance(2);
  const anchorJson = await askJson(
    industry,
    `2026년 글로벌 시장 규모(단위: 십억 달러) 추정치를 3개 소스 관점에서 제시하세요. JSON: {"sources":[{"label":"소스 관점 설명","estimate":2.0,"status":"consensus|excluded","note":"비고"}],"total":2.0}. total은 excluded를 제외한 합의 앵커. status는 뚜렷이 튀는 추정치 하나만 excluded로.`,
  );
  const rawSources = Array.isArray(anchorJson?.sources) ? (anchorJson!.sources as Array<Record<string, unknown>>) : [];
  const anchorSources = rawSources.slice(0, 4).map((s, i) => ({
    label: str(s.label, `소스 관점 #${i + 1} (추정, 검증 전)`),
    estimate: num(s.estimate, 1.0),
    status: (s.status === "excluded" ? "excluded" : "consensus") as "consensus" | "excluded",
    note: `${str(s.note, "")} — LLM 추정, 검증 전`,
  }));
  const anchorTotal =
    num(anchorJson?.total, 0) ||
    r2(anchorSources.filter((s) => s.status === "consensus").reduce((a, s) => a + s.estimate, 0) / Math.max(1, anchorSources.filter((s) => s.status === "consensus").length));
  const s2 = await summarize(industry, 2, "기준 시장규모 산정", `앵커 $${anchorTotal.toFixed(2)}B, 소스 ${anchorSources.length}개(제외 ${anchorSources.filter((s) => s.status === "excluded").length}개). LLM 추정 — 검증 전.`);
  stepSummaries.push({ step: 2, ...s2, pendingInputs: ["실제 밴더 리포트 수치로 교차 확인", "이상치 제외 판단 검토"] });

  // ── Step 3: region weights + segment mixes ──
  advance(3);
  const allocJson = await askJson(
    industry,
    `권역별 가중치와 세그먼트 믹스를 추정하세요. JSON: {"regions":[{"code":"china|apac_ex_china|north_america|europe|mea|latam_row","weight":26,"construction":46,"mining":36,"other":18,"adjustment":"조정 근거 한 문장"}]}. 6개 권역 모두 포함, weight 합계 100, 각 권역의 construction+mining+other=100.`,
  );
  const rawRegions = Array.isArray(allocJson?.regions) ? (allocJson!.regions as Array<Record<string, unknown>>) : [];
  const regions = REGIONS.map((r) => {
    const found = rawRegions.find((x) => str(x.code) === r.code);
    const weight = num(found?.weight, Math.round(100 / REGIONS.length));
    const construction = num(found?.construction, 34);
    const mining = num(found?.mining, 33);
    const other = num(found?.other, 100 - construction - mining);
    return {
      code: r.code,
      label: r.label,
      weight,
      mix: { construction, mining, other },
      adjustment: `${str(found?.adjustment, "LLM 추정 배분")} — 검증 전`,
    };
  });
  const s3 = await summarize(industry, 3, "권역·세그먼트 배분", `6개 권역 × 3개 세그먼트 셀 배분 완료. LLM 추정 — 검증 전.`);
  stepSummaries.push({ step: 3, ...s3, pendingInputs: ["인접 공시시장 프록시로 가중치 검증", "세그먼트 믹스 보정 근거 기록"] });

  // ── Step 4: per-cell baselines + CAGRs + band overrides ──
  advance(4);
  const cagrJson = await askJson(
    industry,
    `권역×세그먼트별 2026 기준 시장규모(십억 달러, 합계≈${anchorTotal.toFixed(2)})와 2026→2030 CAGR(소수)을 추정하세요. JSON: {"baseline":{"china":{"construction":0.2,"mining":0.1,"other":0.05}, ...}, "cagr":{"china":{"construction":0.06, ...}}, "overrides":[{"region":"north_america","segment":"mining","down":0.02,"up":0.11,"reason":"..."}]}. 6개 권역 × construction/mining/other. baseline 합계는 앵커 ${anchorTotal.toFixed(2)}와 ±15% 이내로.`,
  );
  const readMatrix = (obj: unknown): Record<string, Record<string, number>> => {
    const out: Record<string, Record<string, number>> = {};
    if (obj && typeof obj === "object") {
      for (const [region, segs] of Object.entries(obj as Record<string, unknown>)) {
        if (segs && typeof segs === "object") {
          out[region] = {};
          for (const [seg, v] of Object.entries(segs as Record<string, unknown>)) out[region][seg] = num(v, 0);
        }
      }
    }
    return out;
  };
  const llmBaseline = readMatrix(cagrJson?.baseline);
  const llmCagr = readMatrix(cagrJson?.cagr);
  // Scale LLM baselines so the global total reconciles to the anchor.
  const rawTotal = REGIONS.reduce((a, r) => a + SEGMENTS.reduce((b, seg) => b + (llmBaseline[r.code]?.[seg.code] ?? 0), 0), 0);
  const scale = rawTotal > 0 ? anchorTotal / rawTotal : 0;
  const baseline2026: SizingMatrix["baseline2026"] = {};
  const cagrBase: SizingMatrix["cagrBase"] = {};
  for (const r of REGIONS) {
    baseline2026[r.code] = {} as SizingMatrix["baseline2026"][string];
    cagrBase[r.code] = {} as SizingMatrix["cagrBase"][string];
    for (const seg of ["construction", "mining", "other"] as const) {
      const v = (llmBaseline[r.code]?.[seg] ?? anchorTotal / 18) * scale;
      baseline2026[r.code][seg] = Math.round(v * 1000) / 1000;
      cagrBase[r.code][seg] = Math.min(0.25, Math.max(0, llmCagr[r.code]?.[seg] ?? 0.05));
    }
  }
  // 최종 앵커 정합: 라운딩·결측 보간으로 어긋난 합계를 앵커에 정확히 스케일한다.
  const totalNow = REGIONS.reduce((a, r) => a + SEGMENTS.reduce((b, seg) => b + baseline2026[r.code][seg.code], 0), 0);
  if (totalNow > 0) {
    const k = anchorTotal / totalNow;
    for (const r of REGIONS) {
      for (const seg of ["construction", "mining", "other"] as const) {
        baseline2026[r.code][seg] = Math.round(baseline2026[r.code][seg] * k * 1000) / 1000;
      }
    }
  }
  const bandOverrides: SizingMatrix["bandOverrides"] = {};
  if (Array.isArray(cagrJson?.overrides)) {
    for (const o of cagrJson!.overrides as Array<Record<string, unknown>>) {
      const key = `${str(o.region)}|${str(o.segment)}`;
      if (typeof o.down === "number" && typeof o.up === "number") {
        bandOverrides[key] = { down: o.down, up: o.up, reason: str(o.reason, "LLM 제안 wider band") };
      }
    }
  }
  const s4 = await summarize(industry, 4, "셀별 CAGR·시나리오 밴드", `18개 셀 CAGR·기준선 확정(앵커 ${anchorTotal.toFixed(2)}B 스케일 보정). 밴드 오버라이드 ${Object.keys(bandOverrides).length}개.`);
  stepSummaries.push({ step: 4, ...s4, pendingInputs: ["셀별 CAGR 근거(소스) 입력", " wider band 오버라이드 근거 문서화"] });

  // ── Step 5: consistency check (computed, not asked) ──
  advance(5);
  const bottomUpCagr = Math.pow(
    REGIONS.reduce((a, r) => a + SEGMENTS.reduce((b, seg) => b + baseline2026[r.code][seg.code] * Math.pow(1 + cagrBase[r.code][seg.code], 4), 0), 0) / anchorTotal,
    1 / 4,
  ) - 1;
  const s5 = await summarize(
    industry,
    5,
    "성장률 정합성 확인",
    `바텀업 롤업 CAGR ${(bottomUpCagr * 100).toFixed(1)}%. 탑다운 컨센서스 입력 전 — 내부 정합성 확인으로만 사용.`,
  );
  stepSummaries.push({ step: 5, ...s5, pendingInputs: ["탑다운 컨센서스 CAGR 입력"] });

  // ── Step 5-B: external future forecast vs our CAGR extrapolation ──
  // 외부 전망이 입수되면 우리 외삽과의 격차와 그 요인(신규·강화 드라이버)을
  // 분석한다. 입수되지 않으면 externalForecast 없이 기존 방식(CAGR 외삽)을
  // 그대로 사용한다.
  let externalForecast: SizingMatrix["externalForecast"] | undefined;
  const efJson = await askJson(
    industry,
    `이 산업의 공개된 미래 시장 전망치(특정 연도의 시장규모, 십억 달러)를 알고 있는가? JSON: {"available":true,"sourceLabel":"전망 출처(기관/리포트명)","targetYear":2030,"marketSize":3.5,"cagr":0.07,"note":"전망의 전제"}. 알려진 공개 전망이 없으면 {"available":false}만.`,
  );
  if (efJson?.available === true) {
    const targetYear = Math.round(num(efJson.targetYear, 2030));
    const externalSize = num(efJson.marketSize, 0);
    if (externalSize > 0) {
      const yearIndex = Math.max(1, targetYear - 2026);
      const ourSize = REGIONS.reduce((a, r) => a + SEGMENTS.reduce((b, seg) => b + baseline2026[r.code][seg.code] * Math.pow(1 + cagrBase[r.code][seg.code], yearIndex), 0), 0);
      const gapPct = Math.round((externalSize / ourSize - 1) * 1000) / 10;
      const gapJson = await askJson(
        industry,
        `우리 CAGR 외삽 추정(${ourSize.toFixed(2)}B @${targetYear}, CAGR ${(bottomUpCagr * 100).toFixed(1)}%)과 외부 전망(${externalSize.toFixed(2)}B @${targetYear}, 출처: ${str(efJson.sourceLabel, "외부")})이 ${gapPct >= 0 ? "+" : ""}${gapPct}% 차이가 난다. JSON: {"gapAnalysis":"과거 드라이버 외에 어떤 요인이 이 격차를 만드는지 3~5문장","newDrivers":["신규/강화 드라이버", "..."]}. 격차 방향(외부가 높음/낮음)을 명시하고, 수요 촉발 요인·규제·기술 전환·대체재 관점에서 설명하세요.`,
      );
      const newDrivers = (Array.isArray(gapJson?.newDrivers) ? gapJson!.newDrivers : [])
        .filter((d): d is string => typeof d === "string" && d.trim().length > 0)
        .slice(0, 6);
      externalForecast = {
        sourceLabel: str(efJson.sourceLabel, "외부 전망 (검증 전)"),
        targetYear,
        marketSize: externalSize,
        cagr: typeof efJson.cagr === "number" ? efJson.cagr : undefined,
        note: str(efJson.note, "LLM이 제시한 공개 전망 — 출처 확인 필요"),
        ourMarketSize: Math.round(ourSize * 100) / 100,
        gapPct,
        gapAnalysis: typeof gapJson?.gapAnalysis === "string" ? gapJson.gapAnalysis : "격차 요인 분석 미생성 — 수동 작성 필요",
        newDrivers: newDrivers.length ? newDrivers : undefined,
      };
    }
  }
  const s5b = await summarize(
    industry,
    5,
    "외부 전망 대비 격차 분석",
    externalForecast
      ? `외부 전망 입수(${externalForecast.sourceLabel}, ${externalForecast.targetYear}년 ${externalForecast.marketSize.toFixed(2)}B) — 우리 추정 대비 ${externalForecast.gapPct}% 격차, 요인 분석 완료.`
      : "입수된 외부 미래 전망이 없어 기존 방식(CAGR 외삽)을 유지합니다.",
  );
  stepSummaries.push({ step: 5, ...s5b, pendingInputs: externalForecast ? ["외부 전망 출처의 원문 확인"] : [] });

  // ── Step 6: filing cross-validation candidates ──
  advance(6);
  const cvJson = await askJson(
    industry,
    `이 산업의 주요 상장사 관점에서 확인 가능한 매트릭스 주장 3~5개를 제시하세요. JSON: {"claims":[{"claim":"주장","status":"confirmed|directional|impossible","evidence":"근거(공시에서 확인해야 할 구체 항목)"}]}. evidence는 아직 검증 전이므로 '어디를 봐야 하는지'를 적어야 합니다.`,
  );
  const rawClaims = Array.isArray(cvJson?.claims) ? (cvJson!.claims as Array<Record<string, unknown>>) : [];
  const crossValidation = (rawClaims.length
    ? rawClaims
    : [{ claim: "주요 상장사 공시 대조", status: "impossible", evidence: "검증 후보 미생성 — 수동 작성 필요" }]
  ).map((c) => ({
    claim: str(c.claim, "—"),
    status: (["confirmed", "directional", "impossible"].includes(str(c.status)) ? str(c.status) : "directional") as "confirmed" | "directional" | "impossible",
    evidence: str(c.evidence, "—"),
  }));
  const s6 = await summarize(industry, 6, "기업 공시 교차검증", `검증 후보 ${crossValidation.length}개 도출 — 전부 실제 공시 대조 전 상태.`);
  stepSummaries.push({ step: 6, ...s6, pendingInputs: ["각 주장을 실제 연차·중간보고서 원문으로 대조"] });

  // ── Step 6-B: 정성 분석 — 글로벌 기관·증권사·통계 리서치 기반 기회/위험 요인 ──
  // 웹 리서치(TAVILY)로 산업 보고서·증권사 리포트·통계·기사를 입수해 출처와
  // 함께 요인을 도출한다. 리서치 미구성 시 LLM 지식만 사용하고 출처 미확보로
  // 표기한다.
  const research = await researchSources([
    `${industry} 시장 전망 기회 요인 산업 보고서`,
    `${industry} market outlook growth drivers report`,
    `${industry} 산업 통계 수출입 통계`,
  ]);
  const researchContext = research.length
    ? research.map((s, i) => `[${i + 1}] ${s.title} (${s.url})\n${s.snippet}`).join("\n\n")
    : "(웹 리서치 미구성 — LLM 지식 기반)";
  const qualJson = await askJson(
    industry,
    `아래 리서치 발췌를 근거로 이 시장의 정성 분석을 수행하세요. JSON: {"opportunityFactors":["기회 요인", ...],"riskFactors":["위험 요인", ...]}. 각 3~5개 한 문장씩, 발췌에 근거가 있으면 그 출처 번호([n])를 문장 끝에 붙이세요.\n\n리서치 발췌:\n${researchContext}`,
  );
  const listOf = (v: unknown, fallback: string[]): string[] => {
    const arr = Array.isArray(v) ? v : [];
    const items = arr.filter((x): x is string => typeof x === "string" && x.trim().length > 0).slice(0, 5);
    return items.length ? items : fallback;
  };
  const qualitative: SizingMatrix["qualitative"] = {
    opportunityFactors: listOf(qualJson?.opportunityFactors, ["시장 성장 기반 기회 요인 — 정성 분석 보완 필요"]),
    riskFactors: listOf(qualJson?.riskFactors, ["정성 위험 분석 보완 필요"]),
    sources: research.map((s) => ({ title: s.title, url: s.url, snippet: s.snippet.slice(0, 200) })),
  };

  // ── Step 7: limitations ──
  advance(7);
  const limJson = await askJson(
    industry,
    `이 매트릭스의 분석 한계를 4~6개 나열하세요. JSON: {"limitations":["...", "..."]}. 각 항목은 한 문장, 판단적 보정/소스 불일치/외삽 위험을 구체적으로.`,
  );
  const limitations = (Array.isArray(limJson?.limitations) ? limJson!.limitations : [])
    .filter((l): l is string => typeof l === "string" && l.trim().length > 0)
    .slice(0, 6);
  const finalLimitations = limitations.length
    ? limitations
    : ["기준 시장규모 미확정(2단계 수동 입력 대기)", "배분과 CAGR은 LLM 추정 — 소스 대조 전"];
  const s7 = await summarize(industry, 7, "분석 한계 목록", `${finalLimitations.length}개 한계 등록.`);
  stepSummaries.push({ step: 7, ...s7, pendingInputs: [] });

  // ── Step 8: registry (status only — registration happens after freezing) ──
  advance(8);
  const s8 = await summarize(
    industry,
    8,
    "가정 레지스트리 등록",
    "매트릭스가 미동결 상태이므로 미등록. 분석가가 2·4단계 수치를 확정하고 교차검증을 마친 후 recordAssumption으로 등록합니다.",
  );
  stepSummaries.push({ step: 8, ...s8, pendingInputs: [] });

  // ── Assemble the matrix and persist version 1 ──
  const matrix: SizingMatrix = {
    industryLabel: industry,
    provenance: "llm-estimate",
    anchor: { sources: anchorSources, total: anchorTotal },
    regions,
    baseline2026,
    cagrBase,
    bandOverrides: Object.keys(bandOverrides).length ? bandOverrides : undefined,
    chainGrade: {
      grade: "C",
      statisticalHops: 0,
      note: "LLM 추정 매트릭스 — 통계 hop 미확정으로 잠정 C. 분석가가 프록시 체인을 확정하면 재평가합니다.",
    },
    chainDirection,
    qualitative,
    consistency: {
      bottomUpCagr: Math.round(bottomUpCagr * 1000) / 10,
      topDownCagr: 0,
      tolerance: "탑다운 컨센서스 미입력 — 입력 후 재확인 필요. 내부 정합성 확인으로만 사용(독립 검증 아님).",
    },
    externalForecast,
    crossValidation,
    limitations: finalLimitations,
  };

  const payload = JSON.stringify({ methodology: "systematic-market-sizing v1.1.0", matrix, stepSummaries });
  const nextVersionNo =
    ((db.query("SELECT MAX(version_no) m FROM market_sizing_version WHERE analysis_id = ?").get(analysis.id) as { m: number | null }).m ?? 0) + 1;
  const changelog =
    nextVersionNo === 1
      ? "최초 분석 (8단계 LLM 파이프라인 — 추정치, 분석가 확정 전)"
      : `v${nextVersionNo} — LLM 정량 매트릭스 재생성 (8단계 전체)`;
  db.transaction(() => {
    db.run(
      `INSERT INTO market_sizing_version (id, analysis_id, version_no, payload, changelog, created_by, created_at)
       VALUES (?,?,?,?,?,?,?)`,
      [ulid(), analysis.id, nextVersionNo, payload, changelog, "market-sizing-pipeline", now()],
    );
    db.run(
      `UPDATE market_sizing_analysis SET status = 'completed', current_step = 8, completed_at = ? WHERE id = ?`,
      [now(), analysis.id],
    );
  })();
}

function r2(v: number): number {
  return Math.round(v * 100) / 100;
}
